const site=document.querySelector('#site'),app=document.querySelector('#app'),content=document.querySelector('#content'),dialog=document.querySelector('#agent-dialog');let token=sessionStorage.getItem('auven-admin-token')||'',current='overview',hasAccess=false;const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,options={}){const jwt=await window.auvenAuth.accessToken();const bearer=jwt||token;const r=await fetch('/api'+path,{...options,headers:{'content-type':'application/json',...(bearer?{authorization:'Bearer '+bearer}:{}),...options.headers}});let data=await r.json();if(!r.ok)throw Error(data.error||'request_failed');return data}
function openApp(page='overview'){site.hidden=true;app.hidden=false;window.scrollTo(0,0);render(page)}function home(e){e.preventDefault();app.hidden=true;site.hidden=false;window.scrollTo(0,0)}document.querySelectorAll('[data-app]').forEach(b=>b.onclick=()=>openApp(b.dataset.openPage||'overview'));document.querySelectorAll('[data-home]').forEach(b=>b.onclick=home);document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>render(b.dataset.page));document.querySelectorAll('.close').forEach(b=>b.onclick=()=>dialog.close());
const filters={activity:'all',proofs:'all'};
const contextSidebar=document.querySelector('#context-sidebar'),appBody=document.querySelector('#app-body');
function syncContext(page){
  const sections={
    activity:{title:'ACTIVITY',items:[['all','All events'],['allowed','Allowed'],['denied','Denied'],['failed','Failed']]},
    proofs:{title:'PROOFS',items:[['all','All proofs'],['submitted','Submitted'],['local','Not submitted']]}
  };
  const section=hasAccess?sections[page]:null;
  contextSidebar.hidden=!section;
  appBody.classList.toggle('has-context',!!section);
  if(section){
    contextSidebar.innerHTML='<div class="context-title">'+section.title+'</div><nav>'+section.items.map(([value,label])=>'<button type="button" data-context="'+value+'" class="'+(filters[page]===value?'active':'')+'">'+label+'</button>').join('')+'</nav>';
    contextSidebar.querySelectorAll('[data-context]').forEach(button=>button.onclick=()=>{filters[page]=button.dataset.context;render(page)});
  }else contextSidebar.innerHTML='';
  document.querySelectorAll('.app-tabs [data-page]').forEach(button=>button.setAttribute('aria-current',button.dataset.page===page?'page':'false'));
}
const button='<button class="button dark" data-create>+ Connect agent</button>';const empty=(title,copy)=>`<div class="empty"><div class="empty-icon">◈</div><h3>${title}</h3><p>${copy}</p></div>`;
function showError(error){content.innerHTML=`<section class="panel" style="padding:24px;max-width:560px"><h2>Workspace unavailable</h2><p class="subtle">${esc(error.message||error)}</p><button class="button outline" id="retry">Try again</button></section>`;content.querySelector('#retry').onclick=()=>render(current)}
function renderAccess(page){
  if(window.auvenAuth.enabled()){
    content.innerHTML=`<div class="page-top"><div><h1>Sign in to AUVEN</h1><p>Use your email or an EVM wallet on Robinhood Chain.</p></div></div><section class="panel" style="padding:24px;max-width:520px"><form id="email-login"><label>Email address<input name="email" type="email" autocomplete="email" required placeholder="you@example.com"></label><button class="button dark" style="margin-top:20px">Send sign-in code</button></form><form id="email-code" hidden><label>Code from your email<input name="code" inputmode="numeric" autocomplete="one-time-code" required maxlength="8"></label><button class="button dark" style="margin-top:20px">Verify code</button></form><div style="margin:22px 0;border-top:1px solid #eae8ef"></div><button class="button outline" id="wallet-login">Continue with wallet</button><p class="subtle" id="auth-message" style="margin-top:16px"></p></section>`;
    let email='';const message=content.querySelector('#auth-message');
    content.querySelector('#email-login').onsubmit=async e=>{e.preventDefault();email=new FormData(e.target).get('email').trim();try{await window.auvenAuth.emailCode(email);content.querySelector('#email-code').hidden=false;message.textContent='Check your email for the sign-in code.'}catch(error){message.textContent=error.message}};
    content.querySelector('#email-code').onsubmit=async e=>{e.preventDefault();try{await window.auvenAuth.verifyCode(email,new FormData(e.target).get('code').trim());await render(page)}catch(error){message.textContent=error.message}};
    content.querySelector('#wallet-login').onclick=async()=>{message.textContent='Waiting for your wallet…';try{await window.auvenAuth.walletSignIn();await render(page)}catch(error){message.textContent=error.message}};
    return;
  }
  content.innerHTML=`<div class="page-top"><div><h1>Open your workspace</h1><p>Use a workspace token to manage connected agents.</p></div></div><section class="panel" style="padding:24px;max-width:500px"><form id="setup"><label>Workspace name<input name="name" placeholder="My team"></label><label>Existing admin token<input name="token" placeholder="Paste a token to sign in"></label><label>Setup token (if required)<input name="setup" placeholder="Optional"></label><p class="subtle">Create a workspace or paste your existing token. Admin tokens are kept for this browser session only.</p><button class="button dark" style="margin-top:20px">Continue</button><p id="setup-error" class="subtle"></p></form></section>`;
  content.querySelector('#setup').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{if(f.get('token'))token=String(f.get('token')).trim();else{const x=await api('/workspaces',{method:'POST',headers:{'x-setup-token':String(f.get('setup'))},body:JSON.stringify({name:f.get('name')})});token=x.admin_token;alert('Save your workspace admin token now. It will not be shown again:\n\n'+token)}sessionStorage.setItem('auven-admin-token',token);await render(page)}catch(error){token='';sessionStorage.removeItem('auven-admin-token');content.querySelector('#setup-error').textContent=error.message}};
}
function renderWorkspaceSetup(page){
  content.innerHTML=`<div class="page-top"><div><h1>Create your workspace</h1><p>One workspace keeps your connected agents, policies and proofs together.</p></div></div><section class="panel" style="padding:24px;max-width:540px"><form id="new-workspace"><label>Workspace name<input name="name" required minlength="2" maxlength="80" placeholder="Your team"></label><button class="button dark" style="margin-top:20px">Create workspace</button></form><div style="margin:24px 0;border-top:1px solid #eae8ef"></div><form id="claim-workspace"><label>Already have a workspace? Enter its admin token<input name="admin_token" required></label><button class="button outline" style="margin-top:20px">Claim existing workspace</button></form><p class="subtle" id="workspace-message" style="margin-top:16px"></p></section>`;
  const message=content.querySelector('#workspace-message');
  content.querySelector('#new-workspace').onsubmit=async e=>{e.preventDefault();try{const x=await api('/workspaces',{method:'POST',body:JSON.stringify({name:new FormData(e.target).get('name')})});alert('Save this workspace admin token for API access. It will not be shown again:\n\n'+x.admin_token);await render(page)}catch(error){message.textContent=error.message}};
  content.querySelector('#claim-workspace').onsubmit=async e=>{e.preventDefault();try{await api('/workspaces/claim',{method:'POST',body:JSON.stringify({admin_token:new FormData(e.target).get('admin_token')})});await render(page)}catch(error){message.textContent=error.message}};
}
async function render(page){
  current=page;
  await window.auvenAuth.ready;
  const jwt=await window.auvenAuth.accessToken();
  hasAccess=Boolean(jwt||token);
  syncContext(page);
  document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));
  if(!hasAccess){renderAccess(page);return}
  let profile=null;
  if(jwt){
    try{profile=await api('/me');if(!profile.workspace){renderWorkspaceSetup(page);return}}
    catch(error){showError(error);return}
    document.querySelector('.app-workspace-name').textContent=profile.workspace.name;
  }try{let agents=(await api('/agents')).agents;let events=page==='overview'||page==='activity'?(await api('/events')).events:[];const rows=agents.map(a=>`<div class="agent-row" data-agent-search="${esc(a.name+' '+a.purpose)}"><div class="mini-icon violet">◈</div><div><strong>${esc(a.name)}</strong><small>${esc(a.purpose)} · $${(a.daily_limit/100).toFixed(2)} / day</small></div><span class="pill">${esc(a.status)}</span><button class="delete" data-status="${esc(a.id)}" data-next="${a.status==='active'?'stopped':'active'}">${a.status==='active'?'Stop':'Resume'}</button></div>`).join('');
const top=(title,copy,action='')=>`<div class="page-top"><div><h1>${title}</h1><p>${copy}</p></div>${action}</div>`;
if(page==='overview'){
  const onboarding=`<section class="onboarding"><div class="onboarding-rail"><div class="onboarding-track"><span class="onboarding-mark"><img src="logo-mark.svg" alt=""></span><span class="onboarding-line"></span><span class="onboarding-step">01</span><span class="onboarding-line"></span><span class="onboarding-step">02</span><span class="onboarding-line"></span><span class="onboarding-step">03</span></div></div><div class="onboarding-main"><div class="onboarding-kicker">YOUR FIRST STEP</div><h2>Register an agent with AUVEN</h2><p>Connect an agent running in your own application. Name it, set a daily limit, then save the gateway credential shown after registration.</p><div class="onboarding-actions"><button type="button" class="button dark" data-create>Connect your first agent <span>↗</span></button><a class="button outline" href="https://github.com/visionaryeyex/auven/blob/main/docs/AGENT_INTEGRATION.md" target="_blank" rel="noreferrer">Integration guide <span>↗</span></a></div><div class="onboarding-steps"><div><b>01</b><span><strong>Register its identity</strong><small>Tell AUVEN what the agent does.</small></span></div><div><b>02</b><span><strong>Set the boundary</strong><small>Choose its daily spending limit.</small></span></div><div><b>03</b><span><strong>Connect the gateway</strong><small>Use the credential in your server application.</small></span></div></div></div></section>`;
  content.innerHTML=top(agents.length?'Overview':'Welcome to AUVEN',agents.length?'Your connected agents and gateway activity.':'Start by connecting an agent you already run.')+(agents.length?`<div class="stats"><div class="stat"><span>Connected agents</span><strong>${agents.length}</strong></div><div class="stat"><span>Gateway events</span><strong>${events.length}</strong></div><div class="stat"><span>Gateway checks</span><strong style="font-size:19px">Active · Limit · Dedupe</strong></div></div><section class="panel wide-panel"><div class="panel-head"><h2>Agents</h2><button type="button" data-create>+ Connect agent</button></div>${rows}</section>`:onboarding);
}
else if(page==='agents')content.innerHTML=top('Agents','Register and manage agents running in your own applications.',button)+(agents.length?`<div class="agent-toolbar"><label><span class="sr-only">Search agents</span><input type="search" placeholder="Search agents..." data-search-agents></label><span>${agents.length} registered</span></div><section class="panel agent-table"><div class="panel-head"><h2>Registered agents</h2><span>Daily limit · Status</span></div>${rows}</section>`:`<section class="panel agent-empty"><div class="empty-icon">◈</div><h2>No agents yet</h2><p>Connect an external agent to give it an identity, a gateway credential, and a signed passport.</p><button class="button dark" type="button" data-create>Connect your first agent ↗</button></section>`);
else if(page==='activity')content.innerHTML=top('Activity','Gateway requests and policy decisions.')+`<section class="panel">${events.filter(e=>filters.activity==='all'||e.decision===filters.activity).map(e=>`<div class="agent-row"><div><strong>${esc(e.decision)} · ${esc(e.reason)}</strong><small>${esc(e.agent_id)} · ${esc(e.created_at)} · reserved $${(e.reserved/100).toFixed(2)}</small></div></div>`).join('')||empty(filters.activity==='all'?'No activity yet':'No matching events',filters.activity==='all'?'Gateway requests will appear here.':'Try another activity filter.')}</section>`;
else if(page==='proofs'){const proofs=(await api('/proofs')).proofs;content.innerHTML=top('Proofs','ML-DSA-65 signed passports and checkpoints.')+`<div class="notice">Publishing writes the hash of a signed proof to Robinhood Chain mainnet and spends gas. A proof is confirmed only after its transaction is verified.</div><section class="panel">${proofs.filter(x=>filters.proofs==='all'||(filters.proofs==='submitted'?!!x.tx_hash:!x.tx_hash)).map(x=>`<div class="agent-row"><div><strong>${esc(x.kind)} · ${esc(x.agent_id)}</strong><small>${esc(x.created_at)} · ${esc(x.chain_status||'not published')}</small>${x.tx_hash?`<small><a target="_blank" rel="noreferrer" href="https://robinhoodchain.blockscout.com/tx/${esc(x.tx_hash)}">View transaction ↗</a></small>`:''}</div><button class="button outline" data-download="${esc(x.id)}">Export</button>${x.tx_hash?`<button class="button outline" data-check="${esc(x.id)}">Verify</button>`:!x.chain_status?`<button class="button dark" data-publish="${esc(x.id)}">Publish</button>`:''}</div>`).join('')||empty(filters.proofs==='all'?'No proofs yet':'No matching proofs',filters.proofs==='all'?'Passports appear after registration.':'Try another proof filter.')}</section>`;content.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>{const p=proofs.find(x=>x.id===b.dataset.download);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(p.payload,null,2)],{type:'application/json'}));a.download=`auven-proof-${p.id}.json`;a.click();URL.revokeObjectURL(a.href)});content.querySelectorAll('[data-publish]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('/proofs/'+b.dataset.publish+'/publish',{method:'POST'});render('proofs')}catch(e){alert(e.message);render('proofs')}});content.querySelectorAll('[data-check]').forEach(b=>b.onclick=async()=>{try{const x=await api('/proofs/'+b.dataset.check+'/inclusion');alert(x.included?'Confirmed on Robinhood Chain mainnet':'Not confirmed: '+x.reason);render('proofs')}catch(e){alert(e.message)}})}
else if(page==='policies')content.innerHTML=top('Policies','Deterministic gateway controls.')+`<section class="panel" style="padding:24px"><h2>Current policy</h2><p class="subtle">Only registered, active agents with sufficient daily budget can call the configured OpenAI provider. Every request needs an idempotency key. Stop an agent from the Agents page to revoke gateway access.</p></section>`;
else if(profile){content.innerHTML=top('Profile','Manage your verified sign-in methods.')+`<section class="panel" style="padding:24px;max-width:700px"><h2>Email</h2><p class="subtle">${profile.email?esc(profile.email):'No verified email linked yet.'}</p>${profile.email?'':`<form id="add-email"><label>Email address<input type="email" name="email" required autocomplete="email"></label><button class="button outline" style="margin-top:18px">Add email</button></form>`}<h2 style="margin-top:30px">Robinhood Chain wallet</h2><p class="subtle">${profile.wallets.length?profile.wallets.map(esc).join('<br>'):'No wallet linked yet.'}</p>${profile.wallets.length?'':'<button class="button outline" id="link-wallet" style="margin-top:18px">Link wallet</button>'}<p class="subtle" id="profile-message" style="margin-top:16px"></p><button class="button outline" id="signout" style="margin-top:24px">Sign out</button></section>`;const msg=content.querySelector('#profile-message');if(content.querySelector('#link-wallet'))content.querySelector('#link-wallet').onclick=async()=>{try{await window.auvenAuth.linkWallet();await render('settings')}catch(error){msg.textContent=error.message}};if(content.querySelector('#add-email'))content.querySelector('#add-email').onsubmit=async e=>{e.preventDefault();try{await window.auvenAuth.addEmail(new FormData(e.target).get('email'));msg.textContent='Check your email to confirm the new address.'}catch(error){msg.textContent=error.message}}}
else content.innerHTML=top('Settings','Workspace access and network configuration.')+`<section class="panel" style="padding:24px"><h2>Session</h2><p class="subtle">Your admin token is stored only for this browser session.</p><button class="button outline" id="signout">Sign out</button></section>`;
content.querySelectorAll('[data-create]').forEach(b=>b.onclick=()=>dialog.showModal());const agentSearch=content.querySelector('[data-search-agents]');if(agentSearch)agentSearch.oninput=()=>{const query=agentSearch.value.trim().toLowerCase();content.querySelectorAll('[data-agent-search]').forEach(row=>{row.hidden=!row.dataset.agentSearch.toLowerCase().includes(query)})};content.querySelectorAll('[data-status]').forEach(b=>b.onclick=async()=>{try{await api('/agents/'+b.dataset.status+'/status',{method:'PATCH',body:JSON.stringify({status:b.dataset.next})});render(page)}catch(error){showError(error)}});if(document.querySelector('#signout'))document.querySelector('#signout').onclick=async()=>{if(profile)await window.auvenAuth.signOut();token='';sessionStorage.removeItem('auven-admin-token');render('overview')};
}catch(err){showError(err)}}
document.querySelector('#agent-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{const x=await api('/agents',{method:'POST',body:JSON.stringify({name:f.get('name'),purpose:f.get('purpose'),daily_limit_cents:Math.round(Number(f.get('budget'))*100)})});dialog.close();e.target.reset();alert('Save this agent credential now. It will not be shown again:\n\n'+x.agent.credential);render('agents')}catch(err){alert(err.message)}};
window.addEventListener('auven-auth-change',()=>{if(!app.hidden)render(current)});
